type Category = 'Technology' | 'Cultural' | 'Sports' | 'Academic' | 'Competition';
type EventItem = { id: string; title: string; category: Category; description: string; date: string; time: string; location: string; organizer: string; capacity: number; registrationDeadline: string; image: string; status: 'Open' | 'Closed'; };
