type Registration = { id: string; eventId: string; userId: string; name: string; email: string; createdAt: string; status: 'Registered' | 'Cancelled'; attendance?: 'Pending' | 'Present' | 'Absent'; };
type Store = { events: EventItem[]; users: User[]; registrations: Registration[]; currentUser: User | null; };
