function readStore(): Store {
  try {
    const raw = localStorage.getItem(STORE_KEY);
    if (!raw) return seed;
    const parsed = JSON.parse(raw);
    if ((parsed?.version === 1 || parsed?.version === 2) && parsed.data?.events && parsed.data?.users && parsed.data?.registrations) {
      return { ...parsed.data, events: parsed.data.events.map((event: EventItem) => ({ ...event, registrationDeadline: event.registrationDeadline || `${event.date}T00:00` })) } as Store;
    }
  } catch { /* restore clean seed for malformed browser data */ }
  return seed;
}
type AppContextValue = Store & { update: (part: Partial<Store>) => void; toast: (text: string) => void; };
const AppContext = createContext<AppContextValue | null>(null);
const useApp = () => {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error('EventX context unavailable');
  return ctx;
};
const dateLabel = (date: string) => new Date(`${date}T12:00:00`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
const categoryIcon = (cat: string) => cat === 'Technology' ? <Sparkles size={16}/> : cat === 'Cultural' ? <Music2 size={16}/> : cat === 'Sports' ? <Dumbbell size={16}/> : cat === 'Academic' ? <BookOpen size={16}/> : <Trophy size={16}/>;
const artworkClass = (image: string) => `artwork art-${image}`;
const eventImage = (image: string) => image === 'technology' ? `${import.meta.env.BASE_URL}event-images/eventx-tech.jpg` : image === 'culture' ? `${import.meta.env.BASE_URL}event-images/eventx-culture.jpg` : image === 'sports' ? `${import.meta.env.BASE_URL}event-images/eventx-sports.jpg` : '';
function EventArtImage({ image, title }: { image: string; title: string }) {
  const src = eventImage(image);
  return src ? <img className="art-image" src={src} alt="" aria-label={`${title} event artwork`} loading="lazy"/> : null;
}
const eventUrl = (id: string) => `/events/${id}`;

function Brand() {
  return <Link href="/" className="brand" data-testid="link-home"><span className="brand-mark"><GraduationCap size={19}/></span><span>event<span style={{color:'#625bd0'}}>x</span></span></Link>;
}
function ButtonLink({ href, children, quiet = false }: { href: string; children: React.ReactNode; quiet?: boolean }) {
  return <Link href={href} className={`btn ${quiet ? 'btn-quiet' : 'btn-primary'}`}>{children}</Link>;
}
function PublicHeader() {
  const { currentUser, update, toast } = useApp();
  const [open, setOpen] = useState(false);
  const [, navigate] = useLocation();
  const logout = () => { update({ currentUser: null }); toast('You have been signed out.'); navigate('/'); };
  return <header className="page-width site-header">
    <Brand/>
    <nav className="nav-links" aria-label="Main navigation">
      <Link href="/events">Explore events</Link><Link href="/about">About</Link><Link href="/contact">Contact</Link>
      {currentUser ? <Link href={currentUser.role === 'admin' ? '/admin/dashboard' : '/student/dashboard'}>My dashboard</Link> : <Link href="/login">Log in</Link>}
    </nav>
    <div className="header-actions">
      {currentUser ? <button className="btn btn-quiet btn-small" onClick={logout} data-testid="button-logout"><LogOut size={15}/> Sign out</button> : <ButtonLink href="/register">Join EventX <ArrowRight size={15}/></ButtonLink>}
      <button aria-label="Open navigation" className="icon-button mobile-menu" onClick={() => setOpen(!open)} data-testid="button-mobile-menu"><Menu size={19}/></button>
    </div>
    {open && <div className="mobile-nav"><Link onClick={() => setOpen(false)} href="/events">Explore events</Link><Link onClick={() => setOpen(false)} href="/about">About EventX</Link><Link onClick={() => setOpen(false)} href="/contact">Contact</Link>{currentUser ? <Link onClick={() => setOpen(false)} href={currentUser.role === 'admin' ? '/admin/dashboard' : '/student/dashboard'}>My dashboard</Link> : <Link onClick={() => setOpen(false)} href="/login">Log in</Link>}</div>}
  </header>;
}
function Footer() {
  return <footer className="footer"><div className="page-width footer-inner"><div><Brand/><div className="footer-note">A little more campus, a lot more together.</div></div><div className="footer-links"><Link href="/events">Explore events</Link><Link href="/about">About</Link><Link href="/contact">Contact</Link></div><div className="footer-note">© 2026 EventX · Made for campus life</div></div></footer>;
}
function ToastHost() {
  const { toastMessage } = useToastLocal();
  return toastMessage ? <div className="toast" role="status" aria-live="polite"><CheckCircle2 size={16}/>{toastMessage}</div> : null;
}
// Toast is housed in app state without coupling each page to a notification library.
const ToastContext = createContext<{toastMessage: string}>({ toastMessage: '' });
function useToastLocal() { return useContext(ToastContext); }
function EventCard({ event }: { event: EventItem }) {
  const { registrations, currentUser } = useApp();
  const [, navigate] = useLocation();
  const count = registrations.filter(r => r.eventId === event.id && r.status === 'Registered').length;
  const alreadyRegistered = !!currentUser && registrations.some(r=>r.userId===currentUser.id&&r.eventId===event.id&&r.status==='Registered');
  const canRegister = !alreadyRegistered && event.status === 'Open' && new Date(event.registrationDeadline).getTime() > Date.now() && count < event.capacity;
  return <article className="event-card" data-testid={`card-event-${event.id}`}>
    <Link href={eventUrl(event.id)} className={artworkClass(event.image)} aria-label={`View ${event.title}`}><EventArtImage image={event.image} title={event.title}/><span className="art-tag">{categoryIcon(event.category)} {event.category}</span><span className="art-date">{new Date(`${event.date}T12:00:00`).toLocaleDateString('en-US',{month:'short',day:'2-digit'})}</span><span className="art-title">{event.title}</span></Link>
    <div className="event-card-body"><div className="event-meta"><span><CalendarDays size={14}/>{dateLabel(event.date)}</span><span><MapPin size={14}/>{event.location.split('·')[0]}</span></div><h3>{event.title}</h3><p>{event.description}</p><div className="event-card-foot"><span>{alreadyRegistered?'Your spot is saved':`${Math.max(0,event.capacity-count)} spots left`}</span><div className="event-card-actions"><button className="text-link" disabled={!canRegister} onClick={()=>navigate(`${eventUrl(event.id)}?register=1`)}>{alreadyRegistered?'Registered':canRegister?'Register':'Closed'}</button><Link href={eventUrl(event.id)} className="text-link">View details <ArrowUpRight size={14}/></Link></div></div></div>
  </article>;
}
